function updatePilotLevel(hours){const levels=[{hours:0,name:"دانشجوی پرواز"},{hours:50,name:"خلبان فوق‌سبک"},{hours:100,name:"خلبان هواپیمای سبک"},{hours:500,name:"کمک‌خلبان"},{hours:1000,name:"کاپیتان"}];let current=levels[0],next=null;for(let i=0;i<levels.length;i++){if(hours>=levels[i].hours)current=levels[i];else{next=levels[i];break}}const name=document.querySelector("#pilotLevel"),detail=document.querySelector("#pilotLevelDetail"),bar=document.querySelector("#pilotLevelBar");if(!name||!detail||!bar)return;name.textContent=current.name;if(next){const span=next.hours-current.hours,progress=Math.max(0,Math.min(100,((hours-current.hours)/span)*100));detail.textContent="تا "+next.name+": "+Math.max(0,(next.hours-hours).toFixed(1))+" ساعت باقی مانده";bar.style.width=progress+"%"}else{detail.textContent="بالاترین لول ثبت‌شده · 1000+ ساعت";bar.style.width="100%"}}
function drawFlightRatings(history,totalHours){
const stars=totalHours>=500?5:totalHours>=100?4:totalHours>=50?3:totalHours>=10?2:totalHours>0?1:0;
document.querySelector("#ratingStars").textContent="★".repeat(stars)+"☆".repeat(5-stars);
document.querySelector("#ratingLabel").textContent=stars===5?"استاد شبیه‌ساز":stars===4?"باتجربه":stars===3?"پیشرفته":stars===2?"در حال پیشرفت":stars===1?"تازه‌کار":"شروع مسیر";
const badges=[
{label:"اولین پرواز",ok:history.length>=1,detail:"ثبت حداقل یک پرواز"},
{label:"اپراتور منظم",ok:history.length>=5,detail:"ثبت ۵ پرواز"},
{label:"ناوگان متنوع",ok:new Set(history.map(f=>f.aircraft)).size>=5,detail:"پرواز با ۵ نوع هواپیما"},
{label:"پرواز دوربرد",ok:history.some(f=>Number(f.km)>=3000),detail:"ثبت مسیر بیش از ۳۰۰۰ کیلومتر"},
{label:"پرواز جت",ok:history.some(f=>/A320|747|Citation|CJ4/i.test(f.aircraft||"")),detail:"ثبت پرواز با جت"}
];
const host=document.querySelector("#ratingBadges");host.innerHTML="";
badges.forEach(b=>{const item=document.createElement("div");item.className="rating-badge"+(b.ok?" earned":"");const mark=document.createElement("strong");mark.textContent=b.ok?"✓":"·";const label=document.createElement("b");label.textContent=b.label;const detail=document.createElement("small");detail.textContent=b.detail;item.append(mark,label,detail);host.append(item)});
}
